\relax{def-lie-super}
    \normalfont
    A \textbf{Lie superalgebra} is a $\mathfrak{g} = \mathfrak{g}_{\bar0} \oplus \mathfrak{g}_{\bar1}$ superalgebra over a field $\mathbb{K}$ of characteristic $p \not= 2$ equipped with a bilinear operation $[\cdot \mathbin{,} \cdot]$, the Lie superbracket
    \[
        [\cdot \mathbin{,} \cdot] \colon \mathfrak{g} \times \mathfrak{g} \to \mathfrak{g} ,\ (a,b) \mapsto [a,b]
    \relax
    \ifmmode
      \egroup \m@th$\hfil \egroup
      \end{trivlist} 
    \else $$
    \fi

    \noindent satisfying the following properties (for any homogeneous elements $a, b, c \in \mathfrak{g}$):

    \begin{enumerate}
        \setlength{\itemsep}{0pt}                        
        \setlength{\parskip}{0pt}                                      
        \setlength{\topsep}{0pt}
        \@par\hangindent 2em [(i)] Skew-supersymmetry: $[a, b] = -(-1)^{\abs{a}\abs{b}}[b,a]$;
        \@par\hangindent 2em [(ii)] Super Jacobi identity: $[a, [b,c]] = [[a,b], c] + (-1)^{\abs{a}\abs{b}}[b, [a, c]]$;
        \@par\hangindent 2em [(iii)] In the case $p=3$ only, one must add the condition $[a,[a,a]]=0,~\forall a\in \mathfrak{g}_{\bar1}$.
    \end{enumerate}

\normalfont
    Let $\mathcal{A}=\mathcal{A}_{\bar0} \oplus \mathcal{A}_{\bar1}$ be an associative superalgebra. $\mathcal{A}$ can be turned into a Lie superalgebra by defining a new multiplication $[\cdot \mathbin{,} \cdot] \colon \mathcal{A} \times \mathcal{A} \to \mathcal{A}$ such that 

    \begin{equation}
        [a, b] = ab-(-1)^{\abs{a}\abs{b}}ba
        \relax{supercommutator}
    \end{equation}

    \noindent
    for all homogeneous $a, b \in \mathcal{A}$. 
    \relax{example-assoc-superalgebra}

\relax{lsa-def}
    \normalfont
    Let $\mathcal{A}$ be a vector space over a field $\mathbb{K}$ equipped with a bilinear product $(a, b) \mapsto ab$. $\mathcal{A}$ is called a \textit{left-symmetric algebra} (or LSA, for short) if for all $a, b, c \in \mathcal{A}$, the associator 

    \begin{equation}
         (a, b, c) = (ab)c - a(bc), 
    \end{equation}

    \noindent
    is symmetric in $a, b$. That is, 

    \begin{equation}
        (a, b, c) = (b, a, c) \iff (ab)c - a(bc) = (ba)c - b(ac). \relax{lSID}
    \end{equation}

Let $\mathcal{A}$ be a left-symmetric algebra. Then, the commutator

    \begin{equation}
        [a, b]=ab - ba, \quad \forall a, b \in \mathcal{A},
        \relax{commutator}
    \end{equation}

    \noindent
    defines a Lie algebra $\mathfrak{g}(\mathcal{A)}$. This Lie algebra is called the \textbf{sub-adjacent Lie algebra of $\mathcal{A}$}; moreover, $\mathcal{A}$ is called a compatible left-symmetric structure on the Lie algebra $\mathfrak{g}(\mathcal{A)}$. 
    \relax{prop-subadjacent-Lie-algebra}

\normalfont
    Let $\mathcal{A} = \mathcal{A}_{\bar0} \oplus \mathcal{A}_{\bar1}$ be a superalgebra. Then, $\mathcal{A}$ is a \textit{left-symmetric superalgebra} (or LSSA, for short) if the associator 
    \begin{equation}
        (a, b, c) = (ab)c - a(bc)
    \end{equation}

    \noindent
    of $\mathcal{A}$ is supersymmetric in both $a$ and $b$, that is

    \begin{equation}
        (a, b, c) = (-1)^{\abs{a} \abs{b}}(b, a, c), \quad \forall a, b, c \in \mathcal{A}.
    \end{equation}

In the polynomial ring $\mathbb{K}[x_{1},\ldots,x_{n}]$,  we have the following:
    \begin{enumerate}
    \setlength{\itemsep}{0pt}                        
    \setlength{\parskip}{0pt}                                      
    \setlength{\topsep}{0pt}    
        \@par\hangindent 2em [(i)] If $I$ is any ideal of $\mathbb{K}[x_{1},\ldots,x_{n}]$, then there exist $f_{1},\ldots,f_{k} \in \mathbb{K}[x_{1},\ldots,x_{n}]$ such that $I = \langle f_{1}, \ldots,f_{k} \rangle$.

        \@par\hangindent 2em [(ii)] If $I_{1} \subseteq I_{2} \subseteq \cdots \subseteq I_{n} \subseteq \cdots$ is an ascending chain of ideals of $\mathbb{K}[x_{1},\ldots,x_{n}]$, then there exists $N$ such that $I_{N} = I_{N+1} = I_{N+2} = \cdots$.
     \end{enumerate}

Let $I$ be a nonzero ideal of $\mathbb{K}[x_{1},\ldots,x_{n}]$. The following statements are equivalent for a set of nonzero polynomials $G = \{g_{1},\ldots,g_{k}\} \subseteq I$.
    \begin{enumerate}
     \setlength{\itemsep}{0pt}                        
    \setlength{\parskip}{0pt}                                      
    \setlength{\topsep}{0pt}
    \@par\hangindent 2em [(i)] $G$ is a Gröbner basis for I.
    \@par\hangindent 2em [(ii)] $f \in I$ if and only if $f \xrightarrow{\hspace{0.2cm} G \hspace{0.2cm}}_{+} 0$. 
    \@par\hangindent 2em [(iii)] $f \in I$ if and only if $f = \sum\limits_{i=1}^{k} h_{i}g_{i}$ with $\mathrm{lp}(f) = \max\limits_{i \in [1,k]} (\mathrm{lp}(h_{i})\mathrm{lp}(g_{i}))$.
    \@par\hangindent 2em [(iv)] $\mathrm{Lt}(G) = \mathrm{Lt}(I)$.
    \end{enumerate}

\relax{burde-theorem-specialized}
    Let $\mathbb{K}$ be an algebraically closed field of characteristic $p>2$, $\mathfrak{g} \coloneqq \mathfrak{sl}_2(\mathbb{K})$ and consider its standard basis $\langle E, F, H \rangle$.
    Then, $\mathfrak{sl}_2(\mathbb{K})$ admits left-symmetric structures if and only if $p = 3$. In characteristic $3$, these structures are classified into four families, denoted $\mathcal{A}_{1,u,v}$, $\mathcal{A}_{2, \gamma}$, $\mathcal{A}_{3}$, and $\mathcal{A}_{4}$.

If $p=3$, then $\mathfrak{g}$ admits left-symmetric structures. These are the algebras defined by the matrices $\lambda_{E}, \lambda_{F}, \lambda_{H}$ seen later in Eqs. \eqref{lss1}, \eqref{lss2}, \eqref{lss3}, and \eqref{lss4}. 

    Now, assume that $\mathfrak{g}$ admits a left-symmetric structure $M_{\lambda}$ and that $p > 3$. Any left-symmetric structure on $\mathfrak{g}$ induces a Lie algebra representation
    \[
        \lambda \colon  \mathfrak{g} \to \mathrm{End}(\mathfrak{g}), \quad x \mapsto \lambda_{x},
    \relax
    \ifmmode
      \egroup \m@th$\hfil \egroup
      \end{trivlist} 
    \else $$
    \fi
    \noindent
    where $\lambda_{x}(y) \coloneqq x*y$ is the left multiplication by $x$. The vector space $\mathfrak{g}$, equipped with the action $x*v \coloneqq \lambda_x(v)$, therefore becomes a $\mathfrak{g}$-module of dimension $3$, which we denote by $M_{\lambda}$. More information on left-symmetric $\mathfrak{g}$-modules can be found in N\noexpand\thmhead@plainN\csname cite \endcsname{burde1}.

    Since every left-symmetric structure over $\mathbb{K}$ can be defined over the algebraic closure of $\mathbb{K}$, it is enough to prove the following:
    \begin{enumerate}
        \setlength{\itemsep}{0pt}                        
        \setlength{\parskip}{0pt}                                      
        \setlength{\topsep}{0pt}
        \@par\hangindent 2em [(1)] Let $\mathbb{K}$ be an algebraically closed field of characteristic $p > 3$ and $M$ be any $3$-dimensional $\mathfrak{g}$-module. Then, $H^{1}(\mathfrak{g}, M) = 0$.
    \end{enumerate}

    \noindent
    To establish (1), consider the following theorem by Dzhumadil'daev N\noexpand\thmhead@plainN\csname cite \endcsname{dzhumadildaev-cohomology} for $\mathfrak{g} \coloneqq \mathfrak{sl}_{2}(\mathbb{K})$ (Theorem 4): if $\mathbb{K}$ is an algebraically closed field and $E$ is an irreducible $\mathfrak{g}$-module, then
    \begin{enumerate}
        \setlength{\itemsep}{0pt}                        
        \setlength{\parskip}{0pt}                                      
        \setlength{\topsep}{0pt}
        \@par\hangindent 2em [(2)] $H^{1}(\mathfrak{g}, E) \cong \begin{cases}
            \mathbb{K} \oplus \mathbb{K}, &\text{if dim}(E) = p -1,\\ 0, & \text{otherwise.}
        \end{cases}$
    \end{enumerate}
    Consider a composition series for $M$. All irreducible composition factors have dimension at most $3$. Given that $p-1 > 3$, none of these  composition factors have dimension $p-1$, thus all factors have trivial $1$-cohomology by (2). Using the long exact sequence then yields $H^{1}(\mathfrak{g}, M) = 0$, establishing (1).

    Consider now the following proposition (Proposition 1.2.8) found in N\noexpand\thmhead@plainN\csname cite \endcsname{burde1}

    \begin{proposition} \relax{prop-burde}
        Let $\mathfrak{g}$ be a Lie algebra over $\mathbb{K}$ such that $[\mathfrak{g}, \mathfrak{g}] = \mathfrak{g}$ and assume that $\mathfrak{g}$ admits a left-symmetric structure $M_{\lambda}$. Then, $H^{1}(\mathfrak{g}, M_{\lambda}) = 0$ implies $p > 0$ and $p \mid \mathrm{dim}(\mathfrak{g})$.
    \end{proposition}

    \noindent
    Applying (1) to the specialized module $M = M_{\lambda}$ gives $H^{1}(\mathfrak{g}, M_{\lambda}) = 0$. Knowing $[\mathfrak{g}, \mathfrak{g}] = \mathfrak{g}$, where $\mathfrak{g} = \mathfrak{sl}_{2}(\mathbb{K})$, Proposition \ref{prop-burde}, forces $p \mid \mathrm{dim}(\mathfrak{g}) = 3$, contradicting $p > 3$.
